#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

/*
 * @brief Test recursive mutex locking and unlocking
 *
 * @details This test verifies that a mutex can be locked and unlocked
 *          recursively by the same thread. A separate thread is created
 *          to perform the recursive operations.
 *
 * @ingroup kernel_mutex_tests
 */

/* Increased stack size to accommodate potential increased stack usage
 * when CONFIG_USERSPACE is enabled, which disables STACK_SENTINEL
 * and might lead to stack overflows if default sizes are too small.
 * Original value might have been 512 or less.
 */
#define STACK_SIZE 1024

K_MUTEX_DEFINE(recursive_mutex);

static void recursive_mutex_thread_entry(void *p1, void *p2, void *p3)
{
    int ret;
    int *result = (int *)p1;

    /* Acquire mutex recursively 3 times */
    ret = k_mutex_lock(&recursive_mutex, K_FOREVER);
    if (ret != 0) {
        *result = TC_FAIL;
        return;
    }

    ret = k_mutex_lock(&recursive_mutex, K_FOREVER);
    if (ret != 0) {
        /* Unlock once if second lock fails to avoid deadlock on exit */
        k_mutex_unlock(&recursive_mutex);
        *result = TC_FAIL;
        return;
    }

    ret = k_mutex_lock(&recursive_mutex, K_FOREVER);
    if (ret != 0) {
        /* Unlock twice if third lock fails to avoid deadlock on exit */
        k_mutex_unlock(&recursive_mutex);
        k_mutex_unlock(&recursive_mutex);
        *result = TC_FAIL;
        return;
    }

    /* Release mutex recursively 3 times */
    k_mutex_unlock(&recursive_mutex);
    k_mutex_unlock(&recursive_mutex);
    k_mutex_unlock(&recursive_mutex);

    *result = TC_PASS;
}

K_THREAD_STACK_DEFINE(recursive_mutex_stack, STACK_SIZE);
static struct k_thread recursive_mutex_thread;

ZTEST(mutex_api, test_mutex_recursive)
{
    int thread_ret = TC_FAIL;

    k_thread_create(&recursive_mutex_thread, recursive_mutex_stack,
                    K_THREAD_STACK_SIZEOF(recursive_mutex_stack),
                    recursive_mutex_thread_entry,
                    &thread_ret, NULL, NULL,
                    K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

    k_thread_join(&recursive_mutex_thread, K_FOREVER);

    zassert_true(thread_ret == TC_PASS, "thread_ret == TC_PASS is false");
}

void test_main(void)
{
    ztest_suite(mutex_api,
                ztest_unit_test(test_mutex_recursive)
                /* Add other mutex_api tests here if they were in the original file */
               );
    ztest_run_test_suite(mutex_api);
}
